<?php require __DIR__.'/includes/app.php';$id=(int)($_GET['id']??0);$s=db()->prepare("SELECT * FROM actividades WHERE id=? AND estado='publicada'");$s->execute([$id]);$a=$s->fetch();if(!$a){http_response_code(404);exit('Actividad no encontrada');}[$code,$label]=activity_state($a);
$q=db()->prepare("SELECT c.id cupo_id,co.nombre comision,co.reglas,t.hora_inicio,t.hora_fin,c.capacidad,(SELECT COUNT(*) FROM inscripciones i WHERE i.cupo_id=c.id AND i.estado='confirmada') usados FROM cupos c JOIN comisiones co ON co.id=c.comision_id JOIN turnos t ON t.id=c.turno_id WHERE c.actividad_id=? AND c.habilitado=1 AND co.activa=1 AND t.activo=1 ORDER BY co.orden,co.nombre,t.orden,t.hora_inicio");$q->execute([$id]);$rows=$q->fetchAll();$turnos=[];$com=[];foreach($rows as $r){$key=$r['hora_inicio'].'-'.$r['hora_fin'];$turnos[$key]=[substr($r['hora_inicio'],0,5),substr($r['hora_fin'],0,5)];$com[$r['comision']]['reglas']=$r['reglas'];$com[$r['comision']]['slots'][$key]=$r;}
?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=e($a['nombre'])?></title><link rel="stylesheet" href="<?=e(url('assets/css/publico.css'))?>"></head><body><header class="hero"><div><h1><?=e($a['nombre'])?></h1><p><?=e($label)?> · <?=e(fmt_date($a['fecha_actividad']))?></p></div></header><main class="wrap"><section class="intro"><a href="<?=e(url())?>">← Actividades</a><p><?=nl2br(e($a['descripcion']))?></p></section><?php if(!$com):?><section class="empty card"><h2>Aún no hay turnos disponibles</h2><p class="meta">Vuelve a consultar pronto.</p></section><?php endif;?><section class="tablebox"><table><thead><tr><th>Comisión</th><?php foreach($turnos as $t):?><th><?=e($t[0].' - '.$t[1])?></th><?php endforeach;?></tr></thead><tbody><?php foreach($com as $name=>$data):?><tr><th><?=e($name)?><br><small><?=e($data['reglas'])?></small></th><?php foreach($turnos as $k=>$t):$r=$data['slots'][$k]??null;?><td><?php if(!$r):?>No disponible<?php else:$free=max(0,(int)$r['capacidad']-(int)$r['usados']);?><div class="slots"><?php for($i=0;$i<(int)$r['usados'];$i++):?><span class="used">●</span><?php endfor;?><?php for($i=0;$i<$free;$i++):?><span class="free">○</span><?php endfor;?></div><small><?=$free?> cupos libres</small><br><?php if($code==='abierta'&&$free>0):?><a class="btn" href="<?=e(url('registrar.php?cupo='.(int)$r['cupo_id']))?>">Inscribirse</a><?php endif;?><?php endif;?></td><?php endforeach;?></tr><?php endforeach;?></tbody></table></section></main></body></html>
